def subsets(nums):
    values = sorted(nums)
    n = len(values)
    result = []
    for mask in range(1 << n):
        subset = []
        for i in range(n):
            if mask & (1 << i):
                subset.append(values[i])
        duplicate = False
        for existing in result:
            if existing == subset:
                duplicate = True
                break
        if not duplicate:
            result.append(subset)
    return sorted(result)
